
const icon = (kind, extra = '') => {
  const paths = {
    bag: '<path d="M4 8h16l-1 13H5L4 8Z M9 9V6a3 3 0 0 1 6 0v3"/>',
    truck: '<path d="M2 5h12v12H2z M14 9h4l4 4v4h-8"/><circle cx="6" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',
    return: '<path d="M4 10h11a5 5 0 1 1 0 10h-3 M9 5l-5 5 5 5"/>',
    tag: '<path d="M3 4h9l9 9-8 8-10-10V4Z"/><circle cx="7.5" cy="8.5" r="1"/>'
  };
  return '<svg '+extra+' viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[kind]+'</svg>';
};

function homePage(html) {
  return html.replace(/<div class="hero-copy">[\s\S]*?<\/div>/, () =>
    '<div class="hero-copy"><h1>Everyday essentials.<br><em>Favorite finds.</em></h1>'+
    '<p>Practical picks for your kitchen and pets, plus figures and collectibles worth looking for.</p>'+
    '<div class="elv-hero-links"><a class="btn btn-primary" href="/collections/home-kitchen">Shop Home &amp; Kitchen</a>'+
    '<a class="elv-hero-browse" href="#elv-departments">Browse departments <span aria-hidden="true">↓</span></a></div></div>')
    .replace('<nav class="department-hero-grid"', '<nav id="elv-departments" class="department-hero-grid"')
    .replace(/(<a class="department-hero-card" href="[^"]+">[\s\S]*?<strong>[\s\S]*?<\/strong>)(<span>[\s\S]*?<\/span>)(<\/a>)/g,
      '$1$2<span class="elv-card-direction" aria-hidden="true">↗</span>$3')
    .replace('<strong>Free standard U.S. shipping on orders of $149+</strong>', '<strong>'+icon('truck')+' Free standard U.S. shipping on orders of $149+</strong>');
}

function kitchenCatalog(html) {
  const toolbar = '<div class="elv-catalog-filters" hidden><label>Find a product <input type="search" data-kitchen-search placeholder="Search products or brands"></label>'+
    '<label>Brand <select data-kitchen-brand><option value="">All brands</option></select></label>'+
    '<label>Availability <select data-kitchen-availability><option value="">All products</option><option value="ready">Ready to order</option></select></label>'+
    '<label>Sort <select data-kitchen-sort><option value="featured">Featured</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option></select></label>'+
    '<p data-kitchen-results role="status" aria-live="polite"></p></div>';
  return html.replace('<h2 id="kitchen-previews">Shop kitchen brands</h2>', '<h2 id="kitchen-previews">Shop kitchen brands</h2>'+toolbar);
}

function productPage(html) {
  const infos = /(<div class="(?:wrap )?elv-product-information">)/;
  if (!infos.test(html)) return html;
  let out = html
    .replace(/<section class="elv-product-specs"><h2>Product specifications<\/h2>([\s\S]*?)<\/section>/, (_, content) =>
      '<details class="elv-product-specs" id="product-specifications" open><summary>Product specifications</summary>'+content+'</details>')
    .replace('<section class="elv-product-highlights"><h2>About this item</h2>', '<section class="elv-product-highlights" id="about-this-item"><h2>About this item</h2>');
  const specs = out.match(/<details class="elv-product-specs"[\s\S]*?<\/details>/)?.[0] || '';
  const chips = [...specs.matchAll(/<dt\b[^>]*>([^<]+)<\/dt>\s*<dd\b[^>]*>([^<]{1,70})<\/dd>/g)]
    .filter(([,key,val]) => /^(?:material|size(?: or variant)?|dimensions|recommended age|capacity|finish|pack contents|package contents|pieces included)$/i.test(key)
      && !/^(?:N\/A|unknown|unspecified|-)$/i.test(val.trim()))
    .slice(0,3)
    .map(([,key,val])=>'<li><span>'+key+'</span> '+val+'</li>').join('');
  const note = '<div class="elv-pdp-jumps"><a href="#about-this-item">About this item</a><a href="#product-specifications">Specifications</a></div>';
  out = out.replace(/<aside class="retail-buy-box" aria-label="Purchase options">[\s\S]*?<\/aside>/, box => {
    const price = box.match(/\b(\d+\.\d{2})\b/)?.[1];
    if (!price || !/<button[^>]+(?:data-elv-cart-add|data-kitchen-action)/.test(box)) return box;
    const help = '<div class="elv-buy-trust"><a href="/shipping-delivery">'+icon('truck')+' Shipping details</a>'+
      '<a href="/returns">'+icon('return')+' 30-day returns</a></div>';
    return box.replace('>', '><span class="elv-buy-label">Purchase options</span>')
      .replace(/<p>(?:<a href="\/shipping-delivery">[\s\S]*?<\/p>)|<div class="detail-help">[\s\S]*?<\/div>/, '')
      .replace('</aside>', () => help+(chips?'<ul class="elv-pdp-facts">'+chips+'</ul>':'')+note+'</aside>')+
      '<div class="elv-mobile-buy" data-mobile-buy hidden><strong>$'+price+'</strong><button type="button" class="btn btn-primary" data-mobile-add>Add to Cart</button></div>';
  });
  if (!/class="[^"]*retail-reviews/.test(out)) {
    out = out.replace('</main>', '<section class="wrap elv-order-help"><h2>Questions about this item?</h2>'+
      '<p>Ask us about sizing, product details or your order.</p><a href="/contact">Contact Elvarins</a></section></main>');
  }
  return out;
}

const kitchenPhoto = '/media/storefront/kitchen-tools.jpg';
const kitchenPhotoSource = /https:\/\/gir\.co\/cdn\/shop\/files\/GIR-BestsellerSet-10_Pieces-Studio\.webp\?v=1790024511(?:(?:&amp;|&)width=\d+)?/g;

export const featuredKitchenPhoto = '';

export function refreshHtml(html, path) {
  const scope = path==='/' ? 'home' : path.startsWith('/products/') ? 'product' : path.startsWith('/collections/') ? 'collection' : path==='/about' ? 'about' : 'general';
  let out = html.replace(kitchenPhotoSource,kitchenPhoto).replace('/shipping-promo.js?v=1','/shipping-promo.js?v=2').replace('<body>', '<body data-elv-refresh="'+scope+'">')
    .replace('</body>', '<script src="/storefront-refresh.js?v=2" defer></script></body>');
  if (scope==='home') return homePage(out);
  if (scope==='product') return productPage(out);
  if (path==='/collections/home-kitchen') return kitchenCatalog(out);
  if (path==='/about') {
    out = out.replace(/<\/main>/, '<nav class="wrap elv-about-departments" aria-label="Shop our departments"><a href="/collections/home-kitchen">Home &amp; Kitchen</a><a href="/collections/pet-supplies">Pet Supplies</a><a href="/#shop">Toys &amp; Collectibles</a></nav></main>');
  }
  return out;
}

export function refreshCart(source) {
  return source.replace("launcher.innerHTML='Cart <span", () => "launcher.innerHTML='"+icon('bag')+"<span class=\"elv-cart-label\">Cart</span> <span")
    .replace('<p id="elv-cart-status" role="status" aria-live="polite"></p>', '<p id="elv-cart-status" role="status" aria-live="polite"></p><button type="button" class="elv-cart-continue">Continue shopping</button><a class="elv-cart-returns" href="/returns">30-day returns · See policy</a>')
    .replace("dialog.querySelector('[data-cart-close]').addEventListener('click',close);",
      "dialog.querySelector('[data-cart-close]').addEventListener('click',close);dialog.querySelector('.elv-cart-continue').addEventListener('click',close);");
}

export function refreshPromo(source) {
  return source.replaceAll('sessionStorage','localStorage')
    .replace("'elvarins-shipping-offer-149'","'elvarins-shipping-offer-149-v2'")
    .replace('}, 1800);', "}, matchMedia('(max-width: 720px)').matches ? 9000 : 6500);");
}

