export const refreshScript = String.raw`
(() => {
  const sticky = document.querySelector('[data-mobile-buy]');
  const add = document.querySelector('main .retail-buy-box button[data-elv-cart-add]:not([data-elv-buy-now]), main .retail-buy-box [data-kitchen-action="cart"]');
  if (sticky && add && 'IntersectionObserver' in window) {
    const mobile = matchMedia('(max-width: 720px)');
    const update = () => { const r=add.getBoundingClientRect(); sticky.hidden = !mobile.matches || (r.top < window.innerHeight-68 && r.bottom > 0); };
    new IntersectionObserver(update,{rootMargin:'0px 0px -68px 0px'}).observe(add);
    update();
    mobile.addEventListener('change', update);
    sticky.querySelector('[data-mobile-add]').addEventListener('click', () => add.click());
  }

  const search = document.querySelector('[data-kitchen-search]');
  if (!search) return;
  const root = search.closest('section');
  const brand = root.querySelector('[data-kitchen-brand]');
  const availability = root.querySelector('[data-kitchen-availability]');
  const order = root.querySelector('[data-kitchen-sort]');
  const status = root.querySelector('[data-kitchen-results]');
  const groups = [...root.querySelectorAll('section[aria-labelledby^="kitchen-brand-"]')];
  const entries = groups.flatMap(group => {
    const label = group.querySelector('h3').textContent.trim();
    brand.add(new Option(label, label));
    const host = group.querySelector('.help-grid');
    return [...host.querySelectorAll('.kitchen-preview-card')].map(card => {
      const p = card.querySelector('p strong')?.textContent.match(/\$([\d.]+)/)?.[1];
      return {card, group, host, label, price: p ? Number(p) : null};
    });
  });
  const sorted = document.createElement('div');
  sorted.className = 'help-grid elv-filter-results';
  sorted.hidden = true;
  root.append(sorted);

  function render() {
    const query = search.value.toLowerCase().trim().split(/\s+/).filter(Boolean);
    const matches = entries.filter(({card,label,price}) =>
      (!brand.value || brand.value === label) && (!availability.value || price!==null)
      && query.every(word => card.textContent.toLowerCase().includes(word)));
    const show = new Set(matches.map(item => item.card));
    for (const {card,host} of entries) {
      if (card.parentElement !== host) host.append(card);
      card.hidden = !show.has(card);
    }
    const sortByPrice = order.value !== 'featured';
    sorted.hidden = !sortByPrice;
    for (const group of groups) group.hidden = sortByPrice || !matches.some(item => item.group === group);
    if (sortByPrice) {
      const dir = order.value === 'low' ? 1 : -1;
      matches.sort((a,b) => a.price===null ? (b.price===null ? 0 : 1) : b.price===null ? -1 : dir*(a.price-b.price));
      for (const item of matches) sorted.append(item.card);
    }
    status.textContent = matches.length ? matches.length+' products' : 'No matching products. Try a different search or filter.';
  }
  search.addEventListener('input',render);
  for (const select of [brand,availability,order]) select.addEventListener('change',render);
  root.querySelector('.elv-catalog-filters').hidden = false;
  render();
})();
`;
